	private static void assertRowsOpened(Fixture fixture, boolean distinct, String forced) throws Exception {
		long runsBefore = LmdbNativeParallelKernelRows.PARALLEL_RUNS.get();
		LmdbNativeDispatchLoop.Selection<RowCursor> selected = fixture.rowLoop(distinct).forcing(forced).dispatch(null);
		assertThat(selected).isNotNull();
		assertThat(selected.id()).isEqualTo(rowTag(distinct));
		int rows = 0;
		try (RowCursor cursor = selected.value()) {
			while (fixture.row.advance(cursor)) {
				rows++;
				assertThat(fixture.row.slots[1]).isEqualTo(100L + fixture.row.slots[0]);
				assertThat(fixture.row.slots[2]).isEqualTo(200L + fixture.row.slots[0]);
			}
		}
		assertThat(rows).isEqualTo(16);
		assertThat(LmdbNativeParallelKernelRows.PARALLEL_RUNS.get()).isGreaterThan(runsBefore);
		assertThat(fixture.source.opened.get()).isEqualTo(2);
		assertThat(fixture.source.closed.get()).isEqualTo(2);
	}

